INSERT INTO docs_viewer_event (
    event_id, correlation_id, event_type, occurred_at,
    object_id, file_no, user_id, content_sha256
) VALUES (
    CAST(#{eventId} AS uuid), #{correlationId}, #{eventType},
    CAST(#{occurredAt} AS timestamp with time zone),
    #{objectId}, #{fileNo}, #{userId}, #{contentSha256}
)
ON CONFLICT (correlation_id, event_type) DO NOTHING
